-- Metadata for registrations and search (Phase 3: ADR-009, ADR-013).
--
-- `metadata` is a JSON document generated by the format adapter on publish; the domain
-- stores it without interpreting it. `search_text` is the lowercase text that
-- `SearchQueryService` searches. Versions published before this migration are left NULL and
-- `onepackd` backfills them by reading the `.nuspec` from their blob.

ALTER TABLE package_version ADD COLUMN metadata TEXT;
ALTER TABLE package_version ADD COLUMN search_text TEXT;

CREATE INDEX package_version_search ON package_version (feed_id, listed);
